#import "DGCommon.h"
#import <PhotosUI/PhotosUI.h>
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>
#import <Speech/Speech.h>
@interface DGComposer:UIViewController<PHPickerViewControllerDelegate,SFSpeechRecognizerDelegate,UITableViewDataSource,UITableViewDelegate>
@property(nonatomic,strong) DGBridge *bridge;
@property(nonatomic,copy) NSString *work,*parent,*replyTo,*person;
@property(nonatomic,copy) void (^sent)(NSDictionary *item);
@end
@implementation DGComposer{UITextView *_text;UIButton *_imageButton,*_voice,*_emoji;DGImage *_preview;UILabel *_status;UIActivityIndicatorView *_spinner;NSData *_image;NSDictionary *_uploaded;BOOL _sending,_recording;AVAudioEngine *_engine;SFSpeechRecognizer *_recognizer;SFSpeechAudioBufferRecognitionRequest *_speechRequest;SFSpeechRecognitionTask *_speechTask;UITableView *_emojiTable;NSArray *_emojis;NSString *_voicePrefix;}
- (void)viewDidLoad{[super viewDidLoad];self.title=self.parent.length?[@"回复 @" stringByAppendingString:self.person?:@""]:@"发表评论";self.view.backgroundColor=UIColor.systemBackgroundColor;self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemCancel target:self action:@selector(close)];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"发送" style:UIBarButtonItemStyleDone target:self action:@selector(send)];_text=[UITextView new];_text.font=[UIFont systemFontOfSize:17];_text.backgroundColor=UIColor.secondarySystemBackgroundColor;_text.layer.cornerRadius=14;[self.view addSubview:_text];_imageButton=Symbol(@"photo",self,@selector(image));_emoji=Symbol(@"face.smiling",self,@selector(emojis));_voice=Symbol(@"mic",self,@selector(voice));for(UIView *view in @[_imageButton,_emoji,_voice])[self.view addSubview:view];_preview=[DGImage new];_preview.contentMode=UIViewContentModeScaleAspectFit;[self.view addSubview:_preview];_status=Label(12,UIFontWeightRegular);_status.numberOfLines=3;_status.textColor=UIColor.secondaryLabelColor;_status.text=@"支持文字、图片和表情包。语音入口将说话转为文字；发送前可编辑。";[self.view addSubview:_status];_spinner=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[self.view addSubview:_spinner];}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat top=self.view.safeAreaInsets.top,width=self.view.bounds.size.width;_text.frame=CGRectMake(16,top+12,width-32,150);_imageButton.frame=CGRectMake(16,top+172,48,44);_emoji.frame=CGRectMake(76,top+172,48,44);_voice.frame=CGRectMake(136,top+172,48,44);_preview.frame=CGRectMake(width-98,top+170,80,72);_status.frame=CGRectMake(18,top+250,width-36,58);_spinner.frame=CGRectMake(width-47,top+314,28,28);_emojiTable.frame=CGRectMake(0,top+218,width,MAX(80,self.view.bounds.size.height-top-218));}
- (void)close{if(_sending){DGToast(self,@"正在提交，请等待平台结果");return;}[self stopVoice];[self dismissViewControllerAnimated:YES completion:^{[NSNotificationCenter.defaultCenter postNotificationName:@"DGResumePlayback" object:nil];}];}
- (void)image{if(_sending)return;[self stopVoice];PHPickerConfiguration *configuration=[[PHPickerConfiguration alloc]initWithPhotoLibrary:PHPhotoLibrary.sharedPhotoLibrary];configuration.filter=PHPickerFilter.imagesFilter;configuration.selectionLimit=1;configuration.preferredAssetRepresentationMode=PHPickerConfigurationAssetRepresentationModeCurrent;PHPickerViewController *picker=[[PHPickerViewController alloc]initWithConfiguration:configuration];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}
- (void)picker:(PHPickerViewController *)picker didFinishPicking:(NSArray<PHPickerResult *> *)results{[picker dismissViewControllerAnimated:YES completion:nil];NSItemProvider *provider=results.firstObject.itemProvider;if(!provider)return;__weak DGComposer *weak=self;[provider loadDataRepresentationForTypeIdentifier:UTTypeImage.identifier completionHandler:^(NSData *data,NSError *error){if(!data)return;UIImage *image=[UIImage imageWithData:data];if(!image)return;CGImageSourceRef source=CGImageSourceCreateWithData((__bridge CFDataRef)data,NULL);NSString *type=source?(__bridge NSString *)CGImageSourceGetType(source):@"";BOOL original=[@[@"public.jpeg",@"public.png",@"com.compuserve.gif"]containsObject:type];if(source)CFRelease(source);NSData *prepared=original?data:UIImageJPEGRepresentation(image,.85);if(prepared.length>10*1024*1024)prepared=UIImageJPEGRepresentation(image,.65);dispatch_async(dispatch_get_main_queue(),^{DGComposer *self=weak;if(!self)return;if(prepared.length>10*1024*1024){DGToast(self,@"图片超过 10MB，请选择较小文件");return;}self->_image=prepared;self->_uploaded=nil;self->_preview.image=image;self->_status.text=@"图片已选择。再次点图片按钮可替换；点发送才会上传和发表评论。";});}];}
- (void)emojis{if(_emojiTable){[_emojiTable removeFromSuperview];_emojiTable=nil;return;}[_text resignFirstResponder];_emojiTable=[[UITableView alloc]initWithFrame:CGRectZero style:UITableViewStylePlain];_emojiTable.dataSource=self;_emojiTable.delegate=self;[self.view addSubview:_emojiTable];[self.view setNeedsLayout];__weak DGComposer *weak=self;[self.bridge request:@"emoji" parameters:@{} completion:^(NSDictionary *result,NSString *error){DGComposer *self=weak;if(!self)return;self->_emojis=Array(result[@"items"]);[self->_emojiTable reloadData];if(error)DGToast(self,error);}];}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return _emojis.count;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)path{UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];NSDictionary *emoji=_emojis[path.row];cell.textLabel.text=Text(String(emoji[@"name"]));DGImage *image=[[DGImage alloc]initWithFrame:CGRectMake(0,0,32,32)];[image remote:Text(String(emoji[@"url"]))];cell.accessoryView=image;return cell;}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[_text insertText:Text(String(_emojis[path.row][@"name"]))];[_emojiTable removeFromSuperview];_emojiTable=nil;[_text becomeFirstResponder];}
- (void)voice{if(_sending)return;if(_recording){[self stopVoice];return;}[SFSpeechRecognizer requestAuthorization:^(SFSpeechRecognizerAuthorizationStatus status){if(status!=SFSpeechRecognizerAuthorizationStatusAuthorized){DGToast(self,@"请在系统设置允许语音识别");return;}[AVAudioSession.sharedInstance requestRecordPermission:^(BOOL allowed){dispatch_async(dispatch_get_main_queue(),^{if(!allowed){DGToast(self,@"请在系统设置允许麦克风");return;}[self beginVoice];});}];}];}
- (void)beginVoice{_recognizer=[[SFSpeechRecognizer alloc]initWithLocale:[NSLocale localeWithLocaleIdentifier:@"zh-CN"]];if(!_recognizer.isAvailable){DGToast(self,@"语音识别暂不可用");return;}DGMusicStop();[NSNotificationCenter.defaultCenter postNotificationName:@"DGPauseForMicrophone" object:nil];[[AVAudioSession sharedInstance]setCategory:AVAudioSessionCategoryPlayAndRecord mode:AVAudioSessionModeMeasurement options:AVAudioSessionCategoryOptionDefaultToSpeaker error:nil];[[AVAudioSession sharedInstance]setActive:YES error:nil];_engine=[AVAudioEngine new];_speechRequest=[SFSpeechAudioBufferRecognitionRequest new];_speechRequest.shouldReportPartialResults=YES;_voicePrefix=_text.text?:@"";AVAudioFormat *format=[_engine.inputNode outputFormatForBus:0];[_engine.inputNode installTapOnBus:0 bufferSize:1024 format:format block:^(AVAudioPCMBuffer *buffer,AVAudioTime *when){[self->_speechRequest appendAudioPCMBuffer:buffer];}];__weak DGComposer *weak=self;_speechTask=[_recognizer recognitionTaskWithRequest:_speechRequest resultHandler:^(SFSpeechRecognitionResult *result,NSError *error){dispatch_async(dispatch_get_main_queue(),^{DGComposer *self=weak;if(!self)return;if(result)self->_text.text=[self->_voicePrefix stringByAppendingString:result.bestTranscription.formattedString];if(result.isFinal||error)[self stopVoice];});}];NSError *failure=nil;[_engine startAndReturnError:&failure];if(failure){[self stopVoice];DGToast(self,@"麦克风启动失败");return;}_recording=YES;[_voice setImage:[UIImage systemImageNamed:@"stop.circle.fill"] forState:UIControlStateNormal];_status.text=@"正在语音转文字，点击停止后检查并发送。此入口不发布原始录音。";}
- (void)stopVoice{if(!_engine)return;[_engine stop];[_engine.inputNode removeTapOnBus:0];[_speechRequest endAudio];[_speechTask cancel];_speechTask=nil;_speechRequest=nil;_engine=nil;_recording=NO;[_voice setImage:[UIImage systemImageNamed:@"mic"] forState:UIControlStateNormal];[[AVAudioSession sharedInstance]setCategory:AVAudioSessionCategoryPlayback mode:AVAudioSessionModeMoviePlayback options:0 error:nil];[[AVAudioSession sharedInstance]setActive:YES error:nil];}
- (void)send{if(_sending)return;if(![NSUserDefaults.standardUserDefaults boolForKey:@"douglass.comments.write"]){DGToast(self,@"请先在更多设置开启评论及回复");return;}NSString *text=[_text.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!text.length&&!_image.length){DGToast(self,@"请输入内容或选择图片");return;}[self stopVoice];[_text resignFirstResponder];_sending=YES;self.navigationItem.rightBarButtonItem.enabled=NO;[_spinner startAnimating];DGHaptic();if(_image&&!_uploaded){DGUploadCommentImage(self.bridge,_image,^(NSDictionary *result,NSString *error){if(error){[self failure:error];return;}self->_uploaded=result;[self publish:text];});}else[self publish:text];}
- (void)publish:(NSString *)text{self->_status.text=@"正在提交评论，请等待平台确认…";[self.bridge request:@"commentPublish" parameters:@{@"id":self.work,@"text":text,@"parent":self.parent?:@"",@"replyTo":self.replyTo?:@"",@"image":_uploaded?:@{}} completion:^(NSDictionary *result,NSString *error){NSDictionary *item=result[@"item"];if(error||![item isKindOfClass:NSDictionary.class]){[self failure:error?:@"平台未确认评论，草稿已保留"];return;}self->_sending=NO;DGHaptic();if(self.sent)self.sent(item);[self dismissViewControllerAnimated:YES completion:^{[NSNotificationCenter.defaultCenter postNotificationName:@"DGResumePlayback" object:nil];}];}];}
- (void)failure:(NSString *)error{_sending=NO;self.navigationItem.rightBarButtonItem.enabled=YES;[_spinner stopAnimating];_status.text=error;DGToast(self,error);}
- (void)dealloc{[_engine stop];[_speechTask cancel];}
@end
UIViewController *DGMakeCommentComposer(DGBridge *bridge,NSString *work,NSString *parent,NSString *replyTo,NSString *name,void (^sent)(NSDictionary *item)){DGComposer *composer=[DGComposer new];composer.bridge=bridge;composer.work=work;composer.parent=parent;composer.replyTo=replyTo;composer.person=name;composer.sent=sent;DGNavigationController *nav=[[DGNavigationController alloc]initWithRootViewController:composer];nav.modalPresentationStyle=UIModalPresentationPageSheet;nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];nav.sheetPresentationController.prefersGrabberVisible=YES;return nav;}
